    /// <summary>Project a runtime dance term (e.g. a custom pack term) to a Dance.</summary>
    public static Dance FromTerm(VocabularyTerm t) =>
        new(new DanceCode(t.Display?.Code ?? ""), t.Canonical, t.Aliases, "");
}

/// <summary>A parsed dance occurrence: a catalog <see cref="Dance"/> (or <see cref="Dances.Generic"/>) plus the exact text it was
/// read from, tagged with how it entered the field. Its own type so a DanceValue can't be used
/// where another dimension's value is expected (CLAUDE.md guideline 1).</summary>
public readonly record struct DanceValue(Dance Term, string StoredValue, ValueOrigin Origin = ValueOrigin.Stored)
{
    /// <summary>False when the value did not match the catalog (Term == Dances.Generic).</summary>
    public bool IsKnown => !ReferenceEquals(Term, Dances.Generic);
    /// <summary>The catalog form; equals StoredValue for an unknown (Generic has no canonical).</summary>
    public string Canonical => IsKnown ? Term.Canonical : StoredValue;
}

/// <summary>A dance field reading: the parsed values plus the exact original frame string
/// (preserved for byte-for-byte write-back).</summary>
public sealed record DanceField(IReadOnlyList<DanceValue> Values, string RawFrame);

/// <summary>Typed resolver for the dance dimension over a loaded (possibly customized)
/// vocabulary — the matching engine stays Dimension.Resolve; this is a thin typed projection.</summary>
public sealed class DanceView
{
    private readonly Dimension _dim;
    private readonly string _delimiter;

    /// <summary>Wrap a runtime dimension; <paramref name="delimiter"/> is the multi-value separator.</summary>
    public DanceView(Dimension dimension, string delimiter = "; ")
    {
        _dim = dimension;
        _delimiter = string.IsNullOrEmpty(delimiter) ? "; " : delimiter;
    }

    /// <summary>The generic (not-in-catalog) dance term.</summary>
    public Dance Generic => Dances.Generic;

    /// <summary>Resolve one token; a miss returns the generic carrying the raw text. Never null.</summary>
    public DanceValue Resolve(string token)
    {
        var term = _dim.Resolve(token);
        if (term is null) return new DanceValue(Dances.Generic, token);
        var hit = Dances.ById.TryGetValue(term.Id, out var c) ? c : Dances.FromTerm(term);
        return new DanceValue(hit, token);
    }

    /// <summary>Read a whole (multi-value) frame: per-value occurrences + the exact original frame.</summary>
    public DanceField Read(string? rawFrame)
    {
        var frame = rawFrame ?? "";
        var values = new List<DanceValue>();
        foreach (var part in frame.Split([_delimiter], System.StringSplitOptions.None))
        {
            var token = part.Trim();
            if (token.Length == 0) continue;
            values.Add(Resolve(token));
        }
        return new DanceField(values, frame);
    }
}

